老师，不使用泛型，同样可以基于可辨识联合类型实现多态：
&#47;&#47;&#47;&#47; 1. 不使用类
enum Transportations {motorcycle, car, truck}

interface TransportationKnowledge {
    type: Transportations;
}

interface T11 extends TransportationKnowledge {
    make: number;
}

interface T21 extends TransportationKnowledge {
    transmission: string;
    pow: number;
    id: &#39;T2&#39;;
}

interface T31 extends TransportationKnowledge {
    capacity: number;
}

type Transporter = T11 | T21 | T31;

function IsTransporter_1(t: any, target: Transportations): t is Transporter {
    return &#39;type&#39; in t &amp;&amp; t.type === target;
}

function run(t: any) {
    if (IsTransporter_1(t, Transportations.motorcycle)) {
        t
    }
    else if (IsTransporter_1(t, Transportations.car)) {
        t
    }
    else if (IsTransporter_1(t, Transportations.truck)) {
        t
    }
    else {}
}

&#47;&#47; 2. 使用类
abstract class TransportationKnowledge_2 {
    abstract type: Transportations;
}

class T12 extends TransportationKnowledge_2 {
    type =  Transportations.motorcycle as const;
    constructor(
        public make: number
    ) {
        super();
    }
}

class T22 extends TransportationKnowledge_2 {
    type = Transportations.car as const;
    constructor(
        public transmission: string,
        public pow: number,
        public id: string = &#39;T2&#39;
    ) {
        super();
    }
}

class T32 extends TransportationKnowledge_2 {
    type = Transportations.truck as const;
    constructor(
        public capacity: number
    ) {
        super();
    }
}

function IsTransporter_2(t: any, target: new (...args: any) =&gt; TransportationKnowledge_2): t is TransportationKnowledge_2 {
    return t instanceof target;
}

function run_2(t: any) {
    if (IsTransporter_2(t, T12)) {
        t
    }
    else if (IsTransporter_2(t, T22)) {
        t
    }
    else if (IsTransporter_2(t, T32)) {
        t
    }
    else {}
}
老师，能否请您比较一下，使用泛型和不使用泛型的两种思路的优缺点

&#47;&#47; SuperFoo 是一个泛型函数类型，它实例化后的类型是一个带泛型参数的函数类型。这个实例化后的泛型参数函数类型能够被泛型函数赋值。
type SuperFoo&lt;T&gt; = &lt;X&gt;(x: T) =&gt; X;
&#47;&#47; SuperFoo 可以被实例化。实例化后的类型是一个带泛型参数的函数类型。
type SuperFoo_string = SuperFoo&lt;string&gt;;
let f: &lt;X&gt;(x: string) =&gt; X = &lt;X&gt;(x: string) =&gt; {return x as any as X;};
type T = typeof f;
type T2 = T extends SuperFoo_string ? SuperFoo_string extends T ? true : false : false; &#47;&#47; T2 = true
type T3 = &lt;X&gt;(x: string) =&gt; X;
type T4 = T3 extends SuperFoo_string ? SuperFoo_string extends T ? true : false : false; &#47;&#47; T4 = true
&#47;&#47; SuperFoo_string 限制对应的 javascript function 必须声明为带泛型参数的函数
function Foo&lt;X&gt;(a: string): X {return a as any as X;}
let v4: SuperFoo_string = Foo;
let v5: SuperFoo_string = f;
&#47;&#47; f 的调用方式。关键是要么显式声明泛型参数的类型，要么能令编译器推断出函数返回结果的类型。
let v = f&lt;string&gt;(&quot;a&quot;);
let v6: string = f(&quot;a&quot;);
&#47;&#47; 注意下面 v2&#47;v3 的两个错误，SuperFoo_string 限制对应的 javascript function 必须声明为带泛型参数的函数
function foo(x: string): number {return 1;}
let v2: SuperFoo_string = foo;
let v3: SuperFoo_string = (a: string) =&gt; parseFloat(a);

1、解释如下声明：
type SuperFoo&lt;T&gt; = &lt;X&gt;(t: T) =&gt; X

SuperFoo 是一个接受类型参数T的范型函数类型。它表示一个接受类型为T的参数并返回一个类型为X的函数。其中X是在函数内部定义的泛型类型。

const Foo: SuperFoo&lt;number&gt; = &lt;T extends any&gt;(x:number): T =&gt; { &#47;&#47;  T extends any 是为了兼容 支持 jsx 的场景
  return x as T;
}

const v = Foo&lt;1&gt;(1);&#47;&#47; typeof v = 1
2、阅读理解课件中的 t3.ts
function IsTransporter&lt;Target extends Transportations&gt;(t: any, target: Target): t is Transporters[Target] {
    return &#39;type&#39; in t &amp;&amp; t.type === target;
}

function IsTransporter2&lt;Target extends Transportations&gt;(t: T, target: Target): t is Transporters[Target] {
    return [T1, T2, T3].some(T =&gt; t instanceof T &amp;&amp; t.type === target);
}

function IsTransporter3&lt;Target extends new(...args: any[]) =&gt; any&gt;(t: T, target: Target): t is InstanceType&lt;Target&gt; {
    return t instanceof target;
}
let xx!: T;
&#47;&#47; 方式1
switch (true) {
    case IsTransporter(xx, Transportations.motorcycle):
        xx
        break;
    case IsTransporter(xx, Transportations.car):
        xx
        break;
    case IsTransporter(xx, Transportations.truck):
        xx
        break;
}
&#47;&#47; 方式2
switch (true) {
    case IsTransporter3(xx, T1):
        xx
        break;
    case IsTransporter3(xx, T2):
        xx
        break;
    case IsTransporter3(xx, T3):
        xx
        break;
}
1、分析IsTransporter、IsTransporter2、IsTransporte3的实现
IsTransporter 通过 type in t 进行类型收束，确认type属性存在于 t， 然后通过 type 进行判断
IsTransporter2 通过 instance 确认t是否基于 T 来确认 t 上是否存在 type 属性， 然后通过 type 进行判断。相较于 IsTransporter， instance 得到的结果更加安全
IsTransporte3 则是直接判断 t 和 target 是否 是基于相同的构造 函数
2、理解 IsTransporte3的设计与使用
其中 IsTransporter 和 IsTransporter2 都可以使用 方式1 进行断言
其中 IsTransporte3 需要 使用 方式2 进行断言
通过对比断言函数的调用方式以及参数类型，IsTransporte3 是基于构造函数进行判断的，IsTransporter和IsTransporter2则是基于标识型属性判断的

type SuperFoo&lt;T&gt; = &lt;X&gt;(x: T) =&gt; X;

const mySuperFoo: SuperFoo&lt;number&gt; = &lt;X&gt;(x: number): X =&gt; {
    return (x as unknown) as X;
};

const result = mySuperFoo&lt;string&gt;(42);

type ResultType = typeof result; &#47;&#47; type ResultType = string
